window.LD=window.LD||{};window.LD["party/p5"]={"id":"p5","name":"The Green Arrows","poss":"The Green Arrows'","members":["h17","h13","h14"],"leader":"h17","morale":100,"disposition":"friendly","motto":"Hugs after the fighting.","banner":{"c1":"#4caf50","c2":"#2f9e9e","emblem":"arrows"},"loc":"emberdeep","loc_name":"Emberdeep","goal":{"text":"to earn 450 silver between them before the season ends","kind":"purse","done":80,"progress":"2,113 silver, past the 450 aimed for","missed":false,"crew":"The Green Arrows","party":"p5"},"vows":[{"text":"to die rich","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Green Arrows","party":"p5"}],"doing":"last seen delving into Emberdeep","progress":null,"today":["Fought 1 fight: won 1; 4 foes down.","XP: Fenwick +1323, Bramble +1248 (level 22!), Ottoline +1248 (level 22!).","Coin between them: +120 silver.","Came away with 7 ember cores, 5 living coals, a gem.","Ate 6 rations.","Used up 3 torches.","Fenwick: new gear, Sturdy Delver's Strap."],"fights_today":["f221"],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"empty_bedroll","title":"The Empty Bedroll","tone":"sad","meter":"3/4","bpm":65,"diff":4,"day":36,"night":"n82","n":10,"by":null,"lead":{"id":"h14","name":"Ottoline","skill":0.916,"inst":"fiddle"}},"renown":290,"season":{"wins":11,"bosses":0,"floors":4,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":1},"career":{"wins":32,"bosses":2,"floors":15,"gold":0,"deaths":0,"fled":2,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":3},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"carriage","name":"Bumpy","label":"carriage","seats":5,"haul":10,"comfort":-3,"since":87,"desc":"Cushions, curtains and a door that shuts. Every bandit on the road notices.","moves":true,"puller":{"kind":"horse","name":"Turnip","label":"riding horse","colour":"black","owner":null},"paid":[["Bramble",128],["Fenwick",18],["Ottoline",9]]},"pace_gap":0,"rels":[{"party":"p1","score":100},{"party":"p7","score":79},{"party":"p8","score":79},{"party":"p9","score":12}],"events":[{"id":"e435","day":13,"season":1,"sday":13,"kind":"big_move","imp":4,"text":"Old Grizzlemaw, a Dire Wolf and a Wolf fall at last at the bottom of the Wolf Den, brought down by the Green Arrows. On the table: Bramble +52 renown (12th to 3rd) and Fenwick +51 (17th to 4th). The Green Arrows +103 party renown (3rd to 1st among the crews).","heroes":["h13","h17"],"parties":["p5"],"cause":"e404","moves":[{"hero":"h13","gain":52,"from":12,"to":3},{"hero":"h17","gain":51,"from":17,"to":4}],"party_moves":[{"party":"p5","gain":103,"from":3,"to":1}],"fight":"f37"},{"id":"e504","day":15,"season":1,"sday":15,"kind":"goal_done","imp":4,"text":"The Green Arrows can cross it off: earn 300 silver between them before the season ends. Drinks are on them. XP: Fenwick +800 (level 9!), Bramble +800 (level 9!), Ottoline +800 (level 10!).","heroes":["h17","h13","h14"],"parties":["p5"],"xp":{"h17":800,"h13":800,"h14":800}},{"id":"e664","day":20,"season":1,"sday":20,"kind":"delve","imp":1,"text":"The Green Arrows descend into the Ashveil Crypts, partly explored (45%).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e665","day":20,"season":1,"sday":20,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Ashveil Crypts at a push pace: 1 room (the iron-bound door).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":1,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e673","day":20,"season":1,"sday":20,"kind":"talent","imp":2,"text":"Something undead takes one look at Ottoline and falls over on its own.","heroes":["h14"],"parties":["p5"],"loc":"ashveil_crypts","skill":"living_saint"},{"id":"e697","day":21,"season":1,"sday":21,"kind":"fight","imp":2,"text":"The Green Arrows, in fine spirits lately, cut down 3 Risen Dead and 2 Skeletons in the coffin racks on floor 2 of the Ashveil Crypts. Ottoline cleared three of them with a single Cleave. Bramble was wherever the trouble was, every time. Loot: 6 grave dust, 10 bones, 2 trinkets.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f62","foes":["zombie","skeleton","zombie"],"where":"in the coffin racks on floor 2 of the Ashveil Crypts","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e698","day":21,"season":1,"sday":21,"kind":"fight","imp":2,"text":"In the bier hall on floor 2 of the Ashveil Crypts, the Green Arrows square up to 2 Skeleton Archers, a Skeleton and Risen Dead and carry the day. Bramble's Hammer Down took most of the fight out of the skeleton in one go. Loot: 8 bones, 6 crypt-caps, 4 grave dust.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f63","foes":["skeleton_archer","skeleton_archer","skeleton"],"where":"in the bier hall on floor 2 of the Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-23},{"id":"e699","day":21,"season":1,"sday":21,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Ashveil Crypts at a steady pace: 4 rooms (the coffin racks, the chapel of statues, the wake cellar and 1 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["common"],"fears":2,"wild":[]}},{"id":"e717","day":21,"season":1,"sday":21,"kind":"campfire","imp":1,"text":"It rains all day. Fenwick and Ottoline decide it is the other one's fault and are cheerful about it.","heroes":["h17","h14"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e740","day":22,"season":1,"sday":22,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Ashveil Crypts at a steady pace: 4 rooms (the grave-goods store, the gravediggers' bunks, the chaplain's cell and 1 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e741","day":22,"season":1,"sday":22,"kind":"talent","imp":1,"text":"Bramble wakes up with an old ache gone and Ottoline pretending to be asleep. (Living Saint, if anyone's asking.)","heroes":["h14","h13"],"parties":["p5"],"loc":"ashveil_crypts","skill":"living_saint"},{"id":"e749","day":22,"season":1,"sday":22,"kind":"talent","imp":1,"text":"Fenwick opens a rusted chest at the Ashveil Crypts with two pins and some patience. The patience was the hard part.","heroes":["h17"],"parties":["p5"],"loc":"ashveil_crypts","skill":"lockpicking"},{"id":"e770","day":23,"season":1,"sday":23,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Ashveil Crypts at a steady pace: 4 rooms (the drowned niches, the Harrow vault, the family archive and 1 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e771","day":23,"season":1,"sday":23,"kind":"talent","imp":2,"text":"Bramble practises footwork round the fire until Fenwick gets dizzy watching.","heroes":["h13","h17"],"parties":["p5"],"loc":"ashveil_crypts","skill":"blade_dancer"},{"id":"e787","day":23,"season":1,"sday":23,"kind":"campfire","imp":2,"text":"Fenwick and Bramble agree that if anything climbs out of a coffin tonight, Fenwick is the one who says hello.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e804","day":24,"season":1,"sday":24,"kind":"fight","imp":2,"text":"The Green Arrows barely beat 2 Skeleton Archers and 2 Bone Constructs in the skeletons' shift room on floor 3 of the Ashveil Crypts. Fenwick closed it out with Repeater on the skeleton archer. Ottoline kept everyone standing (148 healed, Prayer of Healing doing the heavy lifting). Loot: 38 bones, 7 crypt-caps.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f72","foes":["skeleton_archer","skeleton_archer","bone_construct"],"where":"in the skeletons' shift room on floor 3 of the Ashveil Crypts","won":true,"close":true,"shape":"plain"},{"id":"e805","day":24,"season":1,"sday":24,"kind":"fight","imp":2,"text":"Two Risen Dead and 2 Skeleton Archers stir in the crossing of galleries on floor 3 of the Ashveil Crypts, and the Green Arrows dispatch them for good. Bramble ended it the plain way: Shield Bash, and the skeleton archer on the ground. Loot: 2 remains, 6 bones, 2 crypt-caps.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f73","foes":["zombie","skeleton_archer","skeleton_archer"],"where":"in the crossing of galleries on floor 3 of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-26},{"id":"e806","day":24,"season":1,"sday":24,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Ashveil Crypts at a push pace: 5 rooms (the weeping room, the unmarked grave, the stitching room and 2 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":5,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["common","common"],"fears":1,"wild":[]}},{"id":"e835","day":25,"season":1,"sday":25,"kind":"fight","imp":1,"text":"With Bramble hitting hardest, the Green Arrows dispatch a Wraith in the widows' walk on floor 3 of the Ashveil Crypts. Fenwick wove Tailwind over the others and they felt it. Bramble's Blade Dancer kicked in when it counted. Loot: 5 ectoplasm.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f75","foes":["wraith"],"where":"in the widows' walk on floor 3 of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-30},{"id":"e836","day":25,"season":1,"sday":25,"kind":"gear","imp":3,"text":"In the widows' walk on floor 3 of the Ashveil Crypts, Bramble finds a Grave-Blessed Steel Sword and puts it on. Grave-Blessed: much braver (+7 nerve). It is a step up from anything Bramble could buy.","heroes":["h13"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e837","day":25,"season":1,"sday":25,"kind":"fight","imp":2,"text":"The Green Arrows, in fine spirits lately, make short work of 2 Bone Constructs, a Skeleton Archer and Risen Dead in the stitching room on floor 3 of the Ashveil Crypts. Before Bramble's Hammer Down it could have gone either way. Trip Wire did more for this fight than the scoreboard shows. That was Fenwick. Loot: 38 bones, 2 crypt-caps, 1 trinket.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f76","foes":["skeleton_archer","bone_construct","bone_construct"],"where":"in the stitching room on floor 3 of the Ashveil Crypts","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e838","day":25,"season":1,"sday":25,"kind":"fight","imp":1,"text":"In the articulator's hall on floor 3 of the Ashveil Crypts, the Green Arrows square up to a Bone Construct and carry the day. Fenwick's Trip Wire took the strength out of the bone construct. Ottoline kept everyone standing (60 healed, Prayer of Healing doing the heavy lifting). Loot: 19 bones.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f77","foes":["bone_construct"],"where":"in the articulator's hall on floor 3 of the Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-23},{"id":"e839","day":25,"season":1,"sday":25,"kind":"gear","imp":1,"text":"In the articulator's hall on floor 3 of the Ashveil Crypts, Ottoline finds a Lucky Frame Pack and puts it on. Lucky: finds weak spots a little more often (+2 crit).","heroes":["h14"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e840","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Ashveil Crypts at a steady pace: 4 rooms (the widows' walk, the stitching room, the necromancer's workroom and 1 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":3,"close":0,"gear":["great","great"],"fears":1,"wild":[]}},{"id":"e841","day":25,"season":1,"sday":25,"kind":"talent","imp":1,"text":"Bramble bets Fenwick a silver that Fenwick can't touch Bramble's sleeve with a stick. Fenwick tries for an hour.","heroes":["h13","h17"],"parties":["p5"],"loc":"ashveil_crypts","skill":"wager_of_honour"},{"id":"e909","day":26,"season":1,"sday":26,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Ashveil Crypts at a steady pace: 3 rooms (the last cortege, the grave-goods heap, the sentinel niches).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":3,"size":3,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e910","day":26,"season":1,"sday":26,"kind":"talent","imp":1,"text":"Ottoline stitches Bramble's arm, then asks how Bramble is really doing. The stitches are the quicker job.","heroes":["h14","h13"],"parties":["p5"],"loc":"ashveil_crypts","skill":"field_chaplain"},{"id":"e919","day":26,"season":1,"sday":26,"kind":"talent","imp":1,"text":"Bramble steps neatly round a pressure plate without even looking down. That's Blade Dancer for you.","heroes":["h13"],"parties":["p5"],"loc":"ashveil_crypts","skill":"blade_dancer"},{"id":"e943","day":27,"season":1,"sday":27,"kind":"boss","imp":5,"text":"Two Skeleton Archers and Vessimir the Unburied fall at last at the bottom of the Ashveil Crypts, brought down by the Green Arrows. Bramble's Blade Dancer finished the fight. Ottoline's Hold the Line had everyone hitting harder. Trip Wire, from Fenwick, at exactly the right moment. Bramble's Hammer Down did the damage (2 times). Ottoline flipped the coin before the charge. Heads. \"That was SO fun!\" says Ottoline. Loot: 162 silver each, 10 ectoplasm, 12 grave dust.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f85","foes":["necromancer","skeleton_archer","skeleton_archer"],"where":"at the bottom of The Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-27},{"id":"e944","day":27,"season":1,"sday":27,"kind":"treasure","imp":2,"text":"The Ashveil Crypts gives up its best-kept secret now that Vessimir the Unburied is gone: 11 gold pieces and 6 silver in a locked chest.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","in_fight":"f85"},{"id":"e945","day":27,"season":1,"sday":27,"kind":"race_won","imp":3,"text":"The Green Arrows win the race to Vessimir the Unburied. The bets are paid out in Ashfen before the blood is dry.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","in_fight":"f85"},{"id":"e946","day":27,"season":1,"sday":27,"kind":"gear","imp":4,"text":"Out of the Ashveil Crypts comes Bramble, and with Bramble comes a pale mask with a calm, sleeping face from the lowest crypt: one of a kind, and not yet understood.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e947","day":27,"season":1,"sday":27,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Ashveil Crypts at a push pace: 2 rooms (the Lorne vault, the lowest crypt).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":2,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["unique"],"fears":2,"wild":[]}},{"id":"e948","day":27,"season":1,"sday":27,"kind":"tip_paid","imp":4,"text":"\"The Ashveil Crypts. Go soon.\" Bramble went. Behind a loose stone on the last floor: 126 silver and a note in a hand nobody recognises.","heroes":["h13","h17","h14"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e949","day":27,"season":1,"sday":27,"kind":"delve_done","imp":3,"text":"The Ashveil Crypts is behind The Green Arrows now: 8 days down there, and the sky looks enormous. They got all the way to the bottom, mapped 43% of it, turned up the bier hall, the grave-goods store, the drowned niches and 9 more good rooms, cleared 27 rooms, disarmed 1 trap and came away with 1018 silver between them. The Ashveil Crypts now stands mostly explored (88%), every crew's chalk marks counted.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ashveil_crypts","days":8,"bottom":true,"rooms":["the bier hall","the grave-goods store"],"gold":1018,"turn":"done"},{"id":"e963","day":27,"season":1,"sday":27,"kind":"talent","imp":2,"text":"Bramble drills Fenwick on the parry for an hour. Fenwick's parry is now a real parry. Fencing Lessons: one of the things Bramble learned the long way round.","heroes":["h13","h17"],"parties":["p5"],"loc":"ashveil_crypts","skill":"fencing_lessons"},{"id":"e964","day":27,"season":1,"sday":27,"kind":"campfire","imp":1,"text":"Bramble counts Ottoline's breathing to stay awake on watch, and somewhere along the way it becomes a comfort.","heroes":["h13","h14"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e969","day":27,"season":1,"sday":27,"kind":"big_move","imp":3,"text":"Two Skeleton Archers and Vessimir the Unburied fall at last at the bottom of the Ashveil Crypts, brought down by the Green Arrows. On the table: Bramble +104 renown (6th to 3rd), Ottoline +102 (7th to 5th) and Fenwick +102 (9th to 7th). The Green Arrows +167 party renown (holds 2nd among the crews).","heroes":["h13","h14","h17"],"parties":["p5"],"cause":"e943","moves":[{"hero":"h13","gain":104,"from":6,"to":3},{"hero":"h14","gain":102,"from":7,"to":5},{"hero":"h17","gain":102,"from":9,"to":7}],"party_moves":[{"party":"p5","gain":167,"from":2,"to":2}],"fight":"f85"},{"id":"e998","day":28,"season":1,"sday":28,"kind":"talent","imp":1,"text":"Ottoline talks a nervous young adventurer at the Ashfen tavern through a first wound. It's only a scratch, Ottoline promises. It is.","heroes":["h14"],"parties":["p5"],"loc":"ashfen","skill":"bedside_manner"},{"id":"e1005","day":28,"season":1,"sday":28,"kind":"campfire","imp":1,"text":"Ottoline teaches Bramble a card game. Bramble wins every hand after the first.","heroes":["h14","h13"],"parties":["p5"],"loc":"ashfen"},{"id":"e1019","day":29,"season":1,"sday":29,"kind":"night","imp":1,"text":"Something small and clever gets into The Green Arrows' camp in Bleakmarsh overnight. Bramble wakes up 10 silver and 1 ration lighter.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e1030","day":29,"season":1,"sday":29,"kind":"boss_race","imp":3,"text":"Somebody chalks a tally on the board for the race to Mother Thornmere: The Green Arrows and The Tidal Ledger. Odds are offered, mostly on whoever's buying.","heroes":["h17","h13","h14","h7","h19"],"parties":["p5","p7"],"loc":"thornmere_ruins"},{"id":"e1061","day":30,"season":1,"sday":30,"kind":"meet","imp":2,"text":"Ottoline and Barnaby swap stories in Thornmere Ruins while The Green Arrows and The Tidal Ledger swap rumours.","heroes":["h17","h13","h14","h7","h19"],"parties":["p5","p7"],"loc":"thornmere_ruins"},{"id":"e1067","day":30,"season":1,"sday":30,"kind":"talent","imp":1,"text":"Fenwick picks a campsite with a view, a stream and no mosquitoes. Nobody knows how. That's True Pathfinder for you.","heroes":["h17"],"parties":["p5"],"loc":"thornmere_ruins","skill":"true_pathfinder"},{"id":"e1096","day":31,"season":2,"sday":1,"kind":"bounty","imp":2,"text":"The guild clerk in Thornwall counts out bounties for The Green Arrows until the cashbox is empty: 80 silver each.","heroes":["h17"],"parties":["p5"],"loc":"thornwall","amount":80,"wx":"storm"},{"id":"e1121","day":31,"season":2,"sday":1,"kind":"boss_race","imp":3,"text":"Two crews, one boss. The Scarlet Thorns and The Green Arrows have both set out for Thornmere Ruins. The taverns are taking bets.","heroes":["h6","h9","h17","h13","h14"],"parties":["p1","p5"],"loc":"thornmere_ruins"},{"id":"e1128","day":31,"season":2,"sday":1,"kind":"journey","imp":2,"text":"On the way to Carrbridge, The Green Arrows catch up with The Silver Hounds. The conversation turns to the best way to cook a rat and never recovers.","heroes":["h17","h13","h14","h4","h18","h16"],"parties":["p5","p8"]},{"id":"e1130","day":31,"season":2,"sday":1,"kind":"talent","imp":1,"text":"Fenwick rescues a kite from a Carrbridge chimney for a delighted child. Somebody asks how. 'Rooftop Runner,' says Fenwick.","heroes":["h17"],"parties":["p5"],"loc":"carrbridge","skill":"rooftop_runner","wx":"storm"},{"id":"e1141","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Fenwick and Bramble, a month into The Green Arrows: they walk in step now without trying.","heroes":["h17","h13"],"parties":["p5"],"loc":"carrbridge","wx":"storm"},{"id":"e1150","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from The Green Arrows: to die rich. Easy to say on day one.","heroes":["h17","h13","h14"],"parties":["p5"]},{"id":"e1160","day":32,"season":2,"sday":2,"kind":"party_life","imp":1,"text":"By the third crossroads Fenwick and Ottoline have stopped waiting and started complaining about the wait.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"carrbridge","wx":"storm"},{"id":"e1161","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"Fenwick smokes the day's catch over a slow fire all night. Breakfast is spectacular. Smokehouse: one of the things Fenwick learned the long way round.","heroes":["h17"],"parties":["p5"],"loc":"bleakmarsh","skill":"smokehouse"},{"id":"e1173","day":32,"season":2,"sday":2,"kind":"meet","imp":2,"text":"The Scarlet Thorns run into The Green Arrows in Bleakmarsh. Stories are exchanged, most of them exaggerated.","heroes":["h6","h9","h17","h13","h14"],"parties":["p1","p5"],"loc":"bleakmarsh"},{"id":"e1174","day":32,"season":2,"sday":2,"kind":"journey","imp":1,"text":"The Green Arrows and The Scarlet Thorns walk to Bleakmarsh together. Someone brings up the best way to cook a rat. Someone always does.","heroes":["h17","h13","h14","h6","h9"],"parties":["p5","p1"]},{"id":"e1184","day":33,"season":2,"sday":3,"kind":"party_life","imp":1,"text":"Fenwick and Ottoline wait at every crossroads for Bramble to catch up, and say nothing very loudly.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e1185","day":33,"season":2,"sday":3,"kind":"night","imp":2,"text":"A soldier with old wounds sits at The Green Arrows' fire in Thornmere Ruins and talks about Emberdeep until the fire is ash. He was there once. He won't say when.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1196","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"A month together in The Green Arrows, and Fenwick has finally learned Ottoline's middle name. There are three. It's a long story.","heroes":["h17","h14"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1197","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"Bramble and Ottoline have a month of roads behind them in The Green Arrows, and a dozen stories nobody else is allowed to tell.","heroes":["h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1203","day":34,"season":2,"sday":4,"kind":"delve","imp":1,"text":"The Green Arrows descend into Thornmere Ruins, mostly unexplored (17%).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1204","day":34,"season":2,"sday":4,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Thornmere Ruins at a steady pace: 2 rooms (the scriptorium, the pilgrims' hall).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1227","day":34,"season":2,"sday":4,"kind":"talent","imp":1,"text":"Ottoline sits up with Bramble through a fever, talking about nothing. By morning Bramble is sitting up and asking for breakfast.","heroes":["h14","h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"bedside_manner","wx":"rain"},{"id":"e1248","day":35,"season":2,"sday":5,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Thornmere Ruins at a steady pace: 3 rooms (the temple fish ponds, a sealed space off the temple fish ponds, a worn spiral down from the choir, going under the water).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":["common"],"fears":1,"wild":[]},"wx":"storm"},{"id":"e1265","day":35,"season":2,"sday":5,"kind":"campfire","imp":1,"text":"Fenwick and Bramble split the washing-up by a system so complicated that nobody ends up doing any.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1287","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of Thornmere Ruins at a steady pace: 3 rooms (the sacristy, the reed-choked treasury, the illuminators' desks).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["cosmetic"],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1299","day":36,"season":2,"sday":6,"kind":"talent","imp":2,"text":"Fenwick picks an old cell door at Thornmere Ruins in under a minute. Inside: a fine shield, some boots, a very old rat.","heroes":["h17"],"parties":["p5"],"loc":"thornmere_ruins","skill":"lockpicking","wx":"storm"},{"id":"e1303","day":36,"season":2,"sday":6,"kind":"music","imp":3,"text":"The Green Arrows have an anthem now. It was \"The Empty Bedroll\", sung round the fire until the stars seemed to know the words.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","anthem":"empty_bedroll","night":"n82","wx":"storm"},{"id":"e1305","day":36,"season":2,"sday":6,"kind":"talent","imp":1,"text":"Ottoline freezes a pond's skin with a word and cuts a fishing hole. Dinner comes up through it. Chalk it up to Ice Fishing.","heroes":["h14"],"parties":["p5"],"loc":"thornmere_ruins","skill":"ice_fishing","wx":"storm"},{"id":"e1315","day":37,"season":2,"sday":7,"kind":"fight","imp":3,"text":"Ottoline keeps everyone up as the Green Arrows dispatch a Swamp Troll in the refectory on floor 2 of Thornmere Ruins. Bramble ended it the plain way: Disarm, and the swamp troll on the ground. Ottoline saved Hold the Line for when it mattered. Loot: 16 silver each, 1 troll hide, 5 herbs.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f105","foes":["swamp_troll"],"where":"in the refectory on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-30,"wx":"storm"},{"id":"e1317","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of Thornmere Ruins at a steady pace: 3 rooms (the brewhouse, the refectory, the pipe organ).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common","common"],"fears":2,"wild":[]},"wx":"storm"},{"id":"e1344","day":38,"season":2,"sday":8,"kind":"fight","imp":2,"text":"Three Bog Crawlers and a Siren fall to the Green Arrows in the pond banks on floor 2 of Thornmere Ruins. Before Ottoline's Cleave it could have gone either way. Loot: 13 chitin, 2 bog crawler claws.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f110","foes":["bog_crawler","siren","bog_crawler"],"where":"in the pond banks on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-4,"wx":"storm"},{"id":"e1345","day":38,"season":2,"sday":8,"kind":"wild_room","imp":3,"text":"Ottoline's coin has still never landed wrong. It landed on its edge once, which Ottoline says doesn't count.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","room":"wild_heads_or_tails","wx":"storm"},{"id":"e1346","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of Thornmere Ruins at a push pace: 5 rooms (the pond banks, the cloister walk, the buttery and 2 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":5,"size":3,"floor":2,"traps":2,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":4,"wild":["wild_heads_or_tails"]},"wx":"storm"},{"id":"e1381","day":39,"season":2,"sday":9,"kind":"ambush","imp":3,"text":"The Green Arrows defeat 3 Bounty Hunters and the Bounty Hunters' Captain in Thornmere Ruins, sent for the price on Fenwick's head. Fenwick ended it with Repeater. Bramble did more than her share and started none of the trouble. Loot: 27 silver each, 8 stolen goods, a string of bandit sausages.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f113","foes":["bandit_captain","bandit","bandit"],"where":"in Thornmere Ruins, sent for the price on Fenwick's head","won":true,"close":false,"shape":"plain","wx":"storm"},{"id":"e1382","day":39,"season":2,"sday":9,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of Thornmere Ruins at a steady pace: 2 rooms (the sunken stair, the ossuary).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"storm"},{"id":"e1393","day":39,"season":2,"sday":9,"kind":"campfire","imp":1,"text":"Fenwick and Bramble get lost taking a short cut and blame the map, the sun and the local sheep.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1413","day":40,"season":2,"sday":10,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of Thornmere Ruins at a cautious pace: 2 rooms (the reed maze, the black pool).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"storm"},{"id":"e1414","day":40,"season":2,"sday":10,"kind":"night","imp":2,"text":"Ottoline's ghost story on floor 2 of Thornmere Ruins goes on too long and never really ends. Fenwick lies awake waiting for the ending.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1446","day":41,"season":2,"sday":11,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of Thornmere Ruins at a push pace: 1 room (the cloister garth).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"storm"},{"id":"e1447","day":41,"season":2,"sday":11,"kind":"delve_done","imp":3,"text":"Thornmere Ruins is behind The Green Arrows now: 8 days down there, and the sky looks enormous. They took 20 rooms off the map's blank side, reached the deepest floor, mapped 36% of it, came across a sealed space off the temple fish ponds, the sacristy, the reed-choked treasury and 4 more good rooms, disarmed 1 trap, split 419 silver on the way up and turned back because their nerves were fraying. Thornmere Ruins now stands mostly explored (67%), every crew's chalk marks counted.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","days":8,"bottom":true,"rooms":["a sealed space off the temple fish ponds","the sacristy"],"gold":419,"turn":"nerve","wx":"storm"},{"id":"e1450","day":41,"season":2,"sday":11,"kind":"boss_race","imp":2,"text":"The Green Arrows give up on Mother Thornmere for now, and the race to Thornmere Ruins belongs to The Scarlet Thorns.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1471","day":41,"season":2,"sday":11,"kind":"argument","imp":2,"text":"Ottoline and Fenwick spend supper disagreeing about whose turn it was to keep watch, politely at first.","heroes":["h14","h17"],"parties":["p5"]},{"id":"e1477","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Green Arrows settle on a goal: to see the world: 6 different places before the season ends.","heroes":["h17","h13","h14"],"parties":["p5"]},{"id":"e1492","day":42,"season":2,"sday":12,"kind":"night","imp":2,"text":"Something sings in the dark in Bleakmarsh. Fenwick goes to look and comes back with a trinket and a very quiet manner.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"bleakmarsh","wx":"storm"},{"id":"e1515","day":42,"season":2,"sday":12,"kind":"ability","imp":2,"text":"Fenwick spots fresh boot-prints off the road, says nothing, and quietly picks another route. Ottoline only works it out at supper, and sleeps better for it.","heroes":["h17","h14"],"parties":["p5"],"loc":"bleakmarsh","skill":"true_pathfinder","sk":"True Pathfinder","rule":true,"wx":"storm"},{"id":"e1520","day":42,"season":2,"sday":12,"kind":"campfire","imp":1,"text":"Ottoline and Bramble share the last pickled onion by cutting it exactly in half, with witnesses.","heroes":["h14","h13"],"parties":["p5"],"loc":"bleakmarsh","wx":"storm"},{"id":"e1531","day":43,"season":2,"sday":13,"kind":"party_life","imp":1,"text":"Fenwick and Ottoline ride ahead, ride back, ride ahead again. Bramble is not amused.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"bleakmarsh","wx":"storm"},{"id":"e1548","day":44,"season":2,"sday":14,"kind":"party_life","imp":1,"text":"Bramble arrives at camp an hour behind Fenwick and Ottoline and finds the good spot by the fire taken.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"carrbridge"},{"id":"e1549","day":44,"season":2,"sday":14,"kind":"guide","imp":2,"text":"A guide from Carrbridge, hired by The Green Arrows for 100 silver, walks them to the mouth of the Sunken Vault, points, and goes straight back to the tavern.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"carrbridge"},{"id":"e1567","day":44,"season":2,"sday":14,"kind":"talent","imp":2,"text":"Bramble corrects Ottoline's grip while they walk. Ottoline sighs, then fixes it.","heroes":["h13","h14"],"parties":["p5"],"loc":"carrbridge","skill":"fencing_lessons"},{"id":"e1568","day":44,"season":2,"sday":14,"kind":"talent","imp":1,"text":"Ottoline heals a farmer's lame horse at the roadside. The farmer weeps, then makes everyone lunch.","heroes":["h14"],"parties":["p5"],"loc":"carrbridge","skill":"living_saint"},{"id":"e1630","day":46,"season":2,"sday":16,"kind":"talent","imp":1,"text":"Bramble catches a falling tankard in a crowded Saltmarrow tavern without spilling it. Applause, then free refills.","heroes":["h13"],"parties":["p5"],"loc":"saltmarrow","skill":"blade_dancer","wx":"fog"},{"id":"e1634","day":46,"season":2,"sday":16,"kind":"talent","imp":1,"text":"Fenwick trades a Saltmarrow baker a sourdough starter for a sack of flour. The baker's eyes light up. Trail Baker, the guild calls it.","heroes":["h17"],"parties":["p5"],"loc":"saltmarrow","skill":"trail_baker","wx":"fog"},{"id":"e1642","day":46,"season":2,"sday":16,"kind":"goal_progress","imp":2,"text":"The Green Arrows are getting close: see the world: 6 different places before the season ends (4 of 6 places).","heroes":["h17","h13","h14"],"parties":["p5"]},{"id":"e1664","day":47,"season":2,"sday":17,"kind":"party_life","imp":1,"text":"Bramble asks Fenwick and Ottoline if the view is nice up there. It is.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"saltmarrow","wx":"fog"},{"id":"e1666","day":47,"season":2,"sday":17,"kind":"night_game","imp":3,"text":"A voice drifts from the water, soft as silk: come, sit a while, and play Tide Cards with me. Ottoline wins Tide Cards, and the siren gives up Siren's Pearl Counter with a sigh like a bellows. Fenwick admires Ottoline's nerve at the table, though not enough to say it out loud.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"saltcliffs","night":"n98","monster_game":"siren","wx":"fog"},{"id":"e1688","day":48,"season":2,"sday":18,"kind":"party_life","imp":1,"text":"Bramble spends the whole road in the dust Fenwick and Ottoline kick up, and says so.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"saltcliffs","wx":"fog"},{"id":"e1711","day":48,"season":2,"sday":18,"kind":"goal_done","imp":4,"text":"The Green Arrows can cross it off: see the world: 6 different places before the season ends. Drinks are on them. It was Fenwick's idea in the first place. XP: Fenwick +800, Bramble +927 (level 16!), Ottoline +800 (level 16!).","heroes":["h17","h13","h14"],"parties":["p5"],"xp":{"h17":800,"h13":927,"h14":800}},{"id":"e1714","day":49,"season":2,"sday":19,"kind":"delve","imp":1,"text":"The Green Arrows descend into the Sunken Vault, untouched (0%).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","wx":"fog"},{"id":"e1715","day":49,"season":2,"sday":19,"kind":"fight","imp":3,"text":"In the gatehouse guardroom on floor 1 of the Sunken Vault, the Green Arrows are routed by 4 Drowned. Fenwick hasn't said a word since. Bramble has to be dragged out. Injured: Bramble (bruised ribs).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f122","foes":["drowned","drowned","drowned"],"where":"in the gatehouse guardroom on floor 1 of the Sunken Vault","won":false,"close":true,"shape":"place","reworded":14,"wx":"fog"},{"id":"e1716","day":49,"season":2,"sday":19,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of the Sunken Vault at a push pace: 1 room (the gatehouse guardroom).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"push","stats":{"rooms":1,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":1,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e1717","day":49,"season":2,"sday":19,"kind":"delve_done","imp":1,"text":"The Sunken Vault throws The Green Arrows out after a day, and nobody holds the door. They reached floor 1.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","days":1,"bottom":false,"rooms":[],"gold":0,"out":"Driven out","turn":"routed","wx":"fog"},{"id":"e1736","day":49,"season":2,"sday":19,"kind":"campfire","imp":1,"text":"Fenwick mends Bramble's bootlace with a bit of string and a great deal of confidence.","heroes":["h17","h13"],"parties":["p5"],"loc":"sunken_vault","wx":"fog"},{"id":"e1776","day":51,"season":2,"sday":21,"kind":"ambush","imp":3,"text":"Fenwick takes the worst of it as the Green Arrows handle 3 Drakes on the road to Saltmarrow. The last drake turns tail. The drake couldn't see a thing after Fenwick's Smoke Bomb. Ottoline kept everyone standing (145 healed, Prayer of Healing doing the heavy lifting). Loot: 4 drake scales, 6 fangs & claws, 5 drake flanks.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"saltcliffs","fight":"f126","foes":["drake","drake","drake"],"where":"on the road to Saltmarrow","won":true,"close":false,"shape":"hero","reworded":-38,"wx":"fog"},{"id":"e1794","day":51,"season":2,"sday":21,"kind":"talent","imp":2,"text":"Bramble bets the Saltmarrow tavern that nobody can lay a finger on her. Three try. Nobody manages it. (Wager of Honour, if anyone's asking.)","heroes":["h13"],"parties":["p5"],"loc":"saltmarrow","skill":"wager_of_honour","wx":"fog"},{"id":"e1809","day":51,"season":2,"sday":21,"kind":"ledger","imp":2,"text":"Counters and coin this week: 10 sales, 580 silver changing hands. Biggest haul: Brix, 150 silver in Carrbridge. Back up from the deep: The Sigil of Thornwall (3 days in Cragtooth Warren), The Scarlet Thorns (2 days in Thornmere Ruins), The Green Arrows (1 day in the Sunken Vault), The Thunder of Frosthold (2 days in Frostspire), Juniper's Shields (3 days in the Collapsed Mine) and 1 more.","heroes":["h1","h20","h6","h17"],"parties":["p9","p1","p5"]},{"id":"e1814","day":52,"season":2,"sday":22,"kind":"ambush","imp":3,"text":"In thick fog, the Green Arrows defeat 2 Drakes on the road to the Salt Cliffs. The last drake breaks and runs. Bramble's Disarm took the strength out of the drake. Fenwick saved Tailwind for when it mattered. Bramble picked the biggest one and did not regret it. \"Next,\" says Bramble. Loot: 2 drake scales, 2 drake flanks.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"saltcliffs","fight":"f128","foes":["drake","drake"],"where":"on the road to The Salt Cliffs","won":true,"close":false,"shape":"weather","reworded":-24,"wx":"fog"},{"id":"e1868","day":53,"season":2,"sday":23,"kind":"gift","imp":2,"text":"Fenwick gives Bramble a Goblin's Lucky Spoon. \"For luck,\" Fenwick says, and won't explain further.","heroes":["h17","h13"],"parties":["p5"],"loc":"sunken_vault","wx":"fog"},{"id":"e1872","day":53,"season":2,"sday":23,"kind":"campfire","imp":3,"text":"Bramble finds a soggy ledger and reads Ottoline the worst debts in it in a banker's voice.","heroes":["h14","h13"],"parties":["p5"],"loc":"sunken_vault","wx":"fog"},{"id":"e1881","day":54,"season":2,"sday":24,"kind":"delve","imp":1,"text":"The Green Arrows descend into the Sunken Vault, untouched (0%).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","wx":"fog"},{"id":"e1882","day":54,"season":2,"sday":24,"kind":"fight","imp":3,"text":"Nothing about it is easy, but the Green Arrows barely beat 4 Drowned in the gatehouse guardroom on floor 1 of the Sunken Vault. Bramble ended it with Lunge. Loot: 23 trinkets, 11 barnacle oysters.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f133","foes":["drowned","drowned","drowned"],"where":"in the gatehouse guardroom on floor 1 of the Sunken Vault","won":true,"close":true,"shape":"close","reworded":-30,"wx":"fog"},{"id":"e1883","day":54,"season":2,"sday":24,"kind":"fight","imp":3,"text":"Two Drowned and a Sea Serpent are too much for the Green Arrows in the lower guard-post on floor 1 of the Sunken Vault, and it's time to run for it. Fenwick hasn't said a word since.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f134","foes":["drowned","drowned","sea_serpent"],"where":"in the lower guard-post on floor 1 of the Sunken Vault","won":false,"close":false,"shape":"foe","reworded":-19,"wx":"fog"},{"id":"e1884","day":54,"season":2,"sday":24,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of the Sunken Vault at a push pace: 2 rooms (the gatehouse guardroom, the lower guard-post).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"push","stats":{"rooms":2,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":2,"close":1,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e1885","day":54,"season":2,"sday":24,"kind":"delve_done","imp":1,"text":"The Sunken Vault wins this round: The Green Arrows come up after a day at a fast walk, glancing back the whole way. They took 1 room off the map's blank side and made it to floor 1.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","days":1,"bottom":false,"rooms":[],"gold":0,"out":"Driven out","turn":"routed","wx":"fog"},{"id":"e1999","day":57,"season":2,"sday":27,"kind":"party_life","imp":1,"text":"By the third crossroads Fenwick and Ottoline have stopped waiting and started complaining about the wait.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"saltmarrow"},{"id":"e2046","day":58,"season":2,"sday":28,"kind":"campfire","imp":2,"text":"Fenwick and Ottoline find a pear tree by the road and eat far more than is wise.","heroes":["h17","h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2048","day":58,"season":2,"sday":28,"kind":"ledger","imp":2,"text":"MARKET WEEK: 20 hauls sold across the realm, 2,127 silver all told. Biggest haul: Pickles, 329 silver in Carrbridge. Back up from the deep: The Green Arrows (1 day in the Sunken Vault), The Sigil of Thornwall (1 day in Cragtooth Warren), Brix (1 day in Goblin Camp).","heroes":["h4","h17","h20","h1"],"parties":["p5","p9"]},{"id":"e2062","day":59,"season":2,"sday":29,"kind":"delve","imp":1,"text":"The Green Arrows descend into the Sunken Vault, barely touched (1%).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2066","day":59,"season":2,"sday":29,"kind":"fight","imp":2,"text":"In the lower guard-post on floor 1 of the Sunken Vault, the Green Arrows square up to 2 Sea Serpents and the Drowned and carry the day. Bramble finished the sea serpent with Shield Bash and leaned on her weapon, breathing hard. Ottoline kept everyone standing (174 healed, Prayer of Healing doing the heavy lifting). Loot: 23 fangs & claws, 2 drake scales, 5 trinkets.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f147","foes":["sea_serpent","sea_serpent","drowned"],"where":"in the lower guard-post on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"place","reworded":-13},{"id":"e2067","day":59,"season":2,"sday":29,"kind":"gear","imp":1,"text":"In the lower guard-post on floor 1 of the Sunken Vault, Ottoline finds a Barbute of the Long Night and puts it on. Of the Long Night: much braver (+5 nerve).","heroes":["h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2068","day":59,"season":2,"sday":29,"kind":"fight","imp":2,"text":"The Green Arrows, in fine spirits lately, dispatch 4 Cliff Crabs in the bullion cellar on floor 1 of the Sunken Vault. The last cliff crab decides enough is enough, and goes. Ottoline's Cleave caught the cliff crab square. It stayed down. Loot: 7 chitin, 6 fish, 2 cliff crab claws.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f148","foes":["crab","crab","crab"],"where":"in the bullion cellar on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"mood","reworded":-54},{"id":"e2069","day":59,"season":2,"sday":29,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of the Sunken Vault at a steady pace: 4 rooms (the lower guard-post, the tide-clock, the bullion cellar and 1 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["great"],"fears":3,"wild":[]}},{"id":"e2093","day":60,"season":2,"sday":30,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of the Sunken Vault at a steady pace: 3 rooms (the tide-gate, the assay room, the harbour-light stair).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":3,"wild":[]}},{"id":"e2110","day":60,"season":2,"sday":30,"kind":"delve_done","imp":3,"text":"The Sunken Vault is behind The Green Arrows now: 2 days down there, and the sky looks enormous. They made it to floor 1, took 7 rooms off the map's blank side, found the lower guard-post, the tide-clock, a sealed space off the bullion cellar and 1 more good room and split 177 silver on the way up.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","days":2,"bottom":false,"rooms":["the lower guard-post","the tide-clock"],"gold":177},{"id":"e2160","day":62,"season":3,"sday":2,"kind":"bounty","imp":2,"text":"The guild clerk in Carrbridge counts out bounties for The Green Arrows until the cashbox is empty: 60 silver each.","heroes":["h17"],"parties":["p5"],"loc":"carrbridge","amount":60,"wx":"heat"},{"id":"e2172","day":62,"season":3,"sday":2,"kind":"vow_progress","imp":3,"text":"The Green Arrows swore to die rich on day 1 of season 2. With 3,237 silver earned since, they're rich. Now they just have to stay that way until the age ends.","heroes":["h17","h13","h14"],"parties":["p5"],"cause":"e1150"},{"id":"e2177","day":63,"season":3,"sday":3,"kind":"ambush","imp":2,"text":"The Green Arrows get the better of 4 Wolves on the road to Ironhaven. Ottoline's Turn Undead caught three wolves at once. Bramble accounted for 3 of them, mostly with Hammer Down. Ottoline gave the victory speech nobody asked for. \"Did you SEE that?!\" says Ottoline. Loot: 5 pelts, 2 wolf haunches, 1 fang.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"kingsroad","fight":"f154","foes":["wolf","wolf","wolf"],"where":"on the road to Ironhaven","won":true,"close":false,"shape":"plain","reworded":-13,"wx":"heat"},{"id":"e2197","day":63,"season":3,"sday":3,"kind":"meet","imp":2,"text":"The Green Arrows run into The Tidal Ledger on the road between Carrbridge and Ironhaven. Stories are exchanged, most of them exaggerated.","heroes":["h17","h13","h14","h7","h19"],"parties":["p5","p7"],"loc":"carrbridge","wx":"heat"},{"id":"e2202","day":63,"season":3,"sday":3,"kind":"campfire","imp":1,"text":"Fenwick hangs Bramble's wet socks by the fire with the care of someone hanging a tapestry.","heroes":["h17","h13"],"parties":["p5"],"loc":"ironhaven","wx":"heat"},{"id":"e2229","day":64,"season":3,"sday":4,"kind":"party_life","imp":1,"text":"Bramble arrives at camp an hour behind Fenwick and Ottoline and finds the good spot by the fire taken.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"ironhaven","wx":"heat"},{"id":"e2237","day":64,"season":3,"sday":4,"kind":"ability","imp":2,"text":"Fenwick hears a bridge creak wrong, walks the long way round, and is proven right by a loud splash behind him. It is not his splash.","heroes":["h17"],"parties":["p5"],"loc":"ironhaven","skill":"true_pathfinder","sk":"True Pathfinder","rule":true,"wx":"heat"},{"id":"e2302","day":66,"season":3,"sday":6,"kind":"ambush","imp":2,"text":"Win number four in a row: the Green Arrows see off 2 Bounty Hunters and the Bounty Hunters' Captain on the road out of Veldrock, sent for the price on Bramble's head. Repeater, from Fenwick, was the last thing the bounty hunter saw. Ottoline's Hold the Line turned the fight. Bramble went in first, as usual. Loot: 25 silver each, 11 stolen goods, 4 bandit sausages.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"kingsroad","fight":"f170","foes":["bandit_captain","bandit","bandit"],"where":"on the road out of Veldrock, sent for the price on Bramble's head","won":true,"close":false,"shape":"streak","reworded":-26,"wx":"rain"},{"id":"e2307","day":66,"season":3,"sday":6,"kind":"party_life","imp":1,"text":"Fenwick and Ottoline wait at every crossroads for Bramble to catch up, and say nothing very loudly.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"veldrock","wx":"snow"},{"id":"e2308","day":66,"season":3,"sday":6,"kind":"boss_race","imp":3,"text":"The Kraken of the Vault has visitors coming. The Green Arrows and The Sigil of Thornwall are both on the way to the Sunken Vault, and nobody is waiting for the others.","heroes":["h17","h13","h14","h20","h8"],"parties":["p5","p9"],"loc":"sunken_vault"},{"id":"e2345","day":67,"season":3,"sday":7,"kind":"argument","imp":4,"text":"Enough is enough: Ottoline tells Fenwick exactly what everyone in The Green Arrows has been thinking. Nobody sleeps.","heroes":["h17","h14"],"parties":["p5"]},{"id":"e2366","day":68,"season":3,"sday":8,"kind":"ambush","imp":2,"text":"It's a Bandit and a Bandit Captain against the Green Arrows on the road to Saltmarrow, and it isn't close. The bandit captain lost a turn to Bramble's Shield Bash. Fenwick kept them off everyone with Tailwind. Loot: 21 silver each, 8 stolen goods, 4 bandit sausages.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"kingsroad","fight":"f174","foes":["bandit","bandit_captain"],"where":"on the road to Saltmarrow","won":true,"close":false,"shape":"foe","reworded":-14},{"id":"e2394","day":69,"season":3,"sday":9,"kind":"party_life","imp":3,"text":"Fenwick and Ottoline ride ahead, ride back, ride ahead again. Bramble is not amused.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"saltmarrow"},{"id":"e2397","day":69,"season":3,"sday":9,"kind":"meet","imp":2,"text":"The Sigil of Thornwall and The Green Arrows share a fire in the Salt Cliffs and trade news.","heroes":["h20","h8","h17","h13","h14"],"parties":["p9","p5"],"loc":"saltcliffs"},{"id":"e2401","day":69,"season":3,"sday":9,"kind":"ability","imp":2,"text":"Fenwick decides the ford is too quiet and crosses half a mile upstream. From the far bank he can see the rope strung under the water at the usual crossing. Fenwick walks on, calm as a Sunday.","heroes":["h17"],"parties":["p5"],"loc":"saltcliffs","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e2417","day":70,"season":3,"sday":10,"kind":"party_life","imp":1,"text":"Bramble asks Fenwick and Ottoline if the view is nice up there. It is.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"saltcliffs"},{"id":"e2418","day":70,"season":3,"sday":10,"kind":"night_game","imp":3,"text":"A voice from the ditch on the road to the Sunken Vault says, I will not rob you if you beat me at Tide Cards. The siren climbs out, looking pleased with the terms. Siren's Hand Mirror is the prize, and the siren hands it over as if it hurts, which it does, a bit, but it is also quite proud of it. Fenwick asks Ottoline to teach Tide Cards properly before the next ambush. It looks like they will need it.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","night":"n137","monster_game":"siren"},{"id":"e2451","day":71,"season":3,"sday":11,"kind":"delve","imp":1,"text":"The Green Arrows descend into the Sunken Vault, mostly unexplored (22%).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2452","day":71,"season":3,"sday":11,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Sunken Vault at a push pace: 1 room (the guards' armoury).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"push","stats":{"rooms":1,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2464","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The Green Arrows' plan for the season, as told to the barkeep: to earn 450 silver between them before the season ends.","heroes":["h17","h13","h14"],"parties":["p5"]},{"id":"e2490","day":72,"season":3,"sday":12,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Sunken Vault at a push pace: 4 rooms (the deposit boxes, the tellers' cages, the scriveners' hall and 1 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"push","stats":{"rooms":4,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2491","day":72,"season":3,"sday":12,"kind":"talent","imp":2,"text":"Bramble talks for an hour about a brother back home. Fenwick just listens, which turns out to be the whole job. (Good Listener, if anyone's asking.)","heroes":["h17","h13"],"parties":["p5"],"loc":"sunken_vault","skill":"good_listener"},{"id":"e2521","day":73,"season":3,"sday":13,"kind":"fight","imp":2,"text":"The Green Arrows, in fine spirits lately, cut down 5 Drowned in the guards' barracks on floor 2 of the Sunken Vault. The fight turned on Ottoline's Miracle. Loot: 10 remains, 28 trinkets, 6 barnacle oysters.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f181","foes":["drowned","drowned","drowned"],"where":"in the guards' barracks on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e2522","day":73,"season":3,"sday":13,"kind":"fight","imp":2,"text":"Ottoline keeps everyone up as the Green Arrows defeat 2 Sirens and the Drowned in the depositors' queue on floor 2 of the Sunken Vault. Bramble landed Lunge on the siren hard enough to hear from the back. Ottoline's Hold the Line turned the fight. Loot: 11 trinkets, 5 sea grapes, 1 gem.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f182","foes":["drowned","siren","siren"],"where":"in the depositors' queue on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"hero","reworded":-30},{"id":"e2523","day":73,"season":3,"sday":13,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Sunken Vault at a push pace: 5 rooms (the guards' barracks, the ledger archive, the depositors' queue and 2 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"push","stats":{"rooms":5,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2527","day":73,"season":3,"sday":13,"kind":"gift","imp":2,"text":"By the fire, Ottoline quietly hands Bramble a Siren's Pearl Counter. Bramble pockets it like it's treasure.","heroes":["h14","h13"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2530","day":73,"season":3,"sday":13,"kind":"talent","imp":1,"text":"Ottoline checks the siren's mirror by the fire. It shows the fire from a few seconds ago, which is odd.","heroes":["h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2548","day":74,"season":3,"sday":14,"kind":"fight","imp":2,"text":"The Green Arrows beat 3 Drowned in the drill yard on floor 2 of the Sunken Vault without much fuss. It was Bramble's Blade Dancer that dropped the Drowned. Loot: 23 trinkets, 6 barnacle oysters, 10 remains.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f184","foes":["drowned","drowned","drowned"],"where":"in the drill yard on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e2549","day":74,"season":3,"sday":14,"kind":"fight","imp":2,"text":"In a spiral stair behind the lift-cage on floor 2 of the Sunken Vault, the Green Arrows make short work of 2 Sirens and the Drowned. Bramble found the Drowned with Hammer Down and nearly split it in two. Loot: 12 trinkets, 2 sea grapes.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f185","foes":["drowned","siren","siren"],"where":"in a spiral stair behind the lift-cage on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e2550","day":74,"season":3,"sday":14,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Sunken Vault at a steady pace: 4 rooms (the drill yard, the tide-pool chapel, a spiral stair behind the lift-cage and 1 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":4,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":3,"wild":[]}},{"id":"e2551","day":74,"season":3,"sday":14,"kind":"night","imp":2,"text":"Something small and clever gets into The Green Arrows' camp on floor 2 of the Sunken Vault overnight. Fenwick wakes up 8 silver and 1 ration lighter.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2556","day":74,"season":3,"sday":14,"kind":"talent","imp":1,"text":"Fenwick nets a giant bat at a cave mouth and lets it go once the way is clear.","heroes":["h17"],"parties":["p5"],"loc":"sunken_vault","skill":"spring_net"},{"id":"e2562","day":74,"season":3,"sday":14,"kind":"campfire","imp":1,"text":"Fenwick and Ottoline name every star they can see. Most of the names are made up. All of them are good.","heroes":["h17","h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2587","day":75,"season":3,"sday":15,"kind":"wild_room","imp":3,"text":"Fenwick pressed a button in the Sunken Vault and was rained on with confetti. Nobody can say where the confetti came from.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","room":"wild_the_button"},{"id":"e2588","day":75,"season":3,"sday":15,"kind":"fight","imp":2,"text":"The Green Arrows make it ten wins running, handling 4 Drowned in the counting-house on floor 3 of the Sunken Vault. Fenwick's Bear Trap finished the fight. Without Ottoline's Hold the Line, this goes differently. Loot: 29 trinkets, 13 barnacle oysters.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f193","foes":["drowned","drowned","drowned"],"where":"in the counting-house on floor 3 of the Sunken Vault","won":true,"close":false,"shape":"streak","reworded":-28},{"id":"e2589","day":75,"season":3,"sday":15,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Sunken Vault at a steady pace: 4 rooms (the brass button, the night-chute, the counting-house and 1 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":4,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":3,"wild":["wild_the_button"]}},{"id":"e2596","day":75,"season":3,"sday":15,"kind":"meet","imp":1,"text":"The Green Arrows and The Silver Hounds share a fire in the Sunken Vault. Nobody draws steel, which counts as a good meeting these days.","heroes":["h17","h13","h14","h4","h18","h16"],"parties":["p5","p8"],"loc":"sunken_vault"},{"id":"e2602","day":75,"season":3,"sday":15,"kind":"talent","imp":2,"text":"Fenwick asks Bramble to please, just once, wait for the plan. She promises. She means it, mostly. Bramble puts it down to First Into the Breach.","heroes":["h13","h17"],"parties":["p5"],"loc":"sunken_vault","skill":"first_into_the_breach"},{"id":"e2603","day":75,"season":3,"sday":15,"kind":"campfire","imp":1,"text":"Ottoline buys Fenwick a cheap swill. Then another. Then the conversation gets honest.","heroes":["h14","h17"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2634","day":76,"season":3,"sday":16,"kind":"fight","imp":1,"text":"The Green Arrows send 3 Sirens back to their rest in the siren's rock on floor 3 of the Sunken Vault. Fenwick's Spring Net went in deep, and the siren slowed down after that. Loot: 13 trinkets, 11 sea grapes.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","fight":"f196","foes":["siren","siren","siren"],"where":"in the siren's rock on floor 3 of the Sunken Vault","won":true,"close":false,"shape":"foe","reworded":-19},{"id":"e2635","day":76,"season":3,"sday":16,"kind":"gear","imp":1,"text":"In the siren's rock on floor 3 of the Sunken Vault, Ottoline finds a Salt-Hardened Knight's Heater and puts it on. Salt-Hardened: tougher (+4% health).","heroes":["h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2636","day":76,"season":3,"sday":16,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Sunken Vault at a steady pace: 3 rooms (the diving-bell chamber, the siren's rock, the pearl bed).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":["great"],"fears":2,"wild":[]}},{"id":"e2637","day":76,"season":3,"sday":16,"kind":"talent","imp":1,"text":"Ottoline restocks the party's bandages by tearing up her own spare shirt.","heroes":["h14"],"parties":["p5"],"loc":"sunken_vault","skill":"almshouse_hours"},{"id":"e2668","day":77,"season":3,"sday":17,"kind":"gear","imp":4,"text":"Out of the Sunken Vault comes Ottoline, and with Ottoline comes a belt crusted with tiny shells from the Tide Room: one of a kind, and not yet understood.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2669","day":77,"season":3,"sday":17,"kind":"famous_trap","imp":4,"text":"The Tide Room, the trap everyone in the Sunken Vault talks about, is disarmed at last. Fenwick did it, and kept a piece as proof.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2670","day":77,"season":3,"sday":17,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Sunken Vault at a steady pace: 3 rooms (the wall of the unclaimed, The Tide Room, the cracked foundation).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":3,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":["unique"],"fears":2,"wild":[]}},{"id":"e2671","day":77,"season":3,"sday":17,"kind":"talent","imp":1,"text":"Fenwick tests the net launcher on a pot of stew. Ottoline rescues supper with a fork.","heroes":["h17","h14"],"parties":["p5"],"loc":"sunken_vault","skill":"spring_net"},{"id":"e2679","day":77,"season":3,"sday":17,"kind":"campfire","imp":1,"text":"Fenwick admits to being afraid of statues. Ottoline doesn't laugh. Ottoline just nods and takes the watch nearest it.","heroes":["h14","h17"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2697","day":78,"season":3,"sday":18,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Sunken Vault at a cautious pace: 1 room (the cracked foundation).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","pace":"cautious","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e2698","day":78,"season":3,"sday":18,"kind":"delve_done","imp":3,"text":"The daylight is a shock after 8 days, and The Green Arrows come out into it shading every eye. They made it to floor 3, took the teeth out of 1 trap, took 23 rooms off the map's blank side, mapped 62% of it, found the guards' armoury, the deposit boxes, the tellers' cages and 6 more good rooms, came away with 295 silver between them and turned back because the way on beat them twice, and they mean to come back with more. The Sunken Vault, all crews together: partly explored (52%).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault","days":8,"bottom":false,"rooms":["the guards' armoury","the deposit boxes"],"gold":295,"turn":"blocked"},{"id":"e2703","day":78,"season":3,"sday":18,"kind":"boss_race","imp":2,"text":"The Green Arrows drop out of the race for The Kraken of the Vault. That leaves The Silver Hounds and The Sigil of Thornwall in it.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"sunken_vault"},{"id":"e2732","day":79,"season":3,"sday":19,"kind":"ability","imp":2,"text":"Fenwick spots fresh boot-prints off the road, says nothing, and quietly picks another route. Bramble only works it out at supper, and sleeps better for it.","heroes":["h17","h13"],"parties":["p5"],"loc":"saltcliffs","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e2756","day":80,"season":3,"sday":20,"kind":"party_life","imp":1,"text":"By the third crossroads Fenwick and Ottoline have stopped waiting and started complaining about the wait.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"saltcliffs"},{"id":"e2764","day":80,"season":3,"sday":20,"kind":"talent","imp":1,"text":"Ottoline props the siren's mirror against a mug at Saltmarrow. The whole table folds before a card is dealt.","heroes":["h14"],"parties":["p5"],"loc":"saltmarrow"},{"id":"e2781","day":80,"season":3,"sday":20,"kind":"goal_done","imp":4,"text":"GOAL: The Green Arrows set out to earn 450 silver between them before the season ends, and they have done it, with 10 days to spare. XP: Fenwick +800, Bramble +800, Ottoline +800.","heroes":["h17","h13","h14"],"parties":["p5"],"xp":{"h17":800,"h13":800,"h14":800}},{"id":"e2801","day":81,"season":3,"sday":21,"kind":"talent","imp":2,"text":"Fenwick stops at a quiet bend, frowns, and takes the long way. Later word comes of what was waiting there. Fenwick puts it down to True Pathfinder.","heroes":["h17"],"parties":["p5"],"loc":"saltmarrow","skill":"true_pathfinder"},{"id":"e2838","day":82,"season":3,"sday":22,"kind":"journey","imp":2,"text":"On the way to Carrbridge, The Scarlet Thorns catch up with The Green Arrows. The conversation turns to the best way to cook a rat and never recovers.","heroes":["h6","h9","h17","h13","h14"],"parties":["p1","p5"]},{"id":"e2839","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Bramble pours a capful of homebrew for Fenwick at a rest stop. Fenwick coughs, then holds the cup out again.","heroes":["h13","h17"],"parties":["p5"],"loc":"saltmarrow","skill":"brewer"},{"id":"e2853","day":83,"season":3,"sday":23,"kind":"bounty","imp":2,"text":"The Green Arrows cash in a season's worth of trophies at the Carrbridge guild: about 120 silver a head.","heroes":["h17"],"parties":["p5"],"loc":"carrbridge","amount":120,"wx":"rain"},{"id":"e2929","day":85,"season":3,"sday":25,"kind":"ability","imp":2,"text":"Fenwick stops at a quiet bend, frowns, and takes the long way. Later word comes of the bandits who waited there all day. The crew walks a little taller.","heroes":["h17"],"parties":["p5"],"loc":"ironhaven","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e2979","day":87,"season":3,"sday":27,"kind":"wagon","imp":3,"text":"The Green Arrows chip in 155 silver for a carriage in Veldrock and name it Bumpy. Who paid: Bramble 128, Fenwick 18, Ottoline 9.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"veldrock"},{"id":"e2983","day":87,"season":3,"sday":27,"kind":"gift","imp":2,"text":"By the fire, Ottoline quietly hands Fenwick a Siren's Hand Mirror. Fenwick pockets it like it's treasure.","heroes":["h14","h17"],"parties":["p5"],"loc":"veldrock"},{"id":"e2984","day":87,"season":3,"sday":27,"kind":"talent","imp":2,"text":"A farmer near Veldrock recognises Fenwick from a fox trap that's still working, and presses a dozen eggs on him.","heroes":["h17"],"parties":["p5"],"loc":"veldrock","skill":"trap_seller"},{"id":"e3002","day":88,"season":3,"sday":28,"kind":"talent","imp":1,"text":"Fenwick wakes up with an old ache gone and Ottoline pretending to be asleep.","heroes":["h14","h17"],"parties":["p5"],"loc":"emberdeep","skill":"living_saint"},{"id":"e3003","day":88,"season":3,"sday":28,"kind":"ambush","imp":3,"text":"The Green Arrows, in fine spirits lately, beat 2 Fire Elementals and a Salamander at their camp in Emberdeep, in the middle of the night. Bear Trap, from Fenwick, was the last thing the fire elemental saw. Ask the others what won it: Bramble's First Into the Breach. Ottoline touched the coin in her pocket at the worst moment. The moment passed. Loot: 5 salamander tails.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"emberdeep","fight":"f217","foes":["salamander","fire_elemental","fire_elemental"],"where":"at their camp in Emberdeep, in the middle of the night","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e3017","day":88,"season":3,"sday":28,"kind":"talent","imp":1,"text":"Bramble steps neatly round a pressure plate without even looking down. Blade Dancer all the way, Bramble insists.","heroes":["h13"],"parties":["p5"],"loc":"emberdeep","skill":"blade_dancer"},{"id":"e3034","day":89,"season":3,"sday":29,"kind":"delve","imp":1,"text":"The Green Arrows descend into Emberdeep, untouched (0%).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"emberdeep","wx":"snow"},{"id":"e3035","day":89,"season":3,"sday":29,"kind":"trap","imp":2,"text":"Bramble springs a flame vent in the gate-wards on floor 1 of Emberdeep (bruised ribs) (Ottoline hurt too).","heroes":["h13","h14"],"parties":["p5"],"loc":"emberdeep","wx":"snow"},{"id":"e3036","day":89,"season":3,"sday":29,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Emberdeep at a push pace: 4 rooms (the smoking cleft, the gate-wards, the ash slope and 1 more).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"emberdeep","pace":"push","stats":{"rooms":4,"size":3,"floor":1,"traps":1,"sprung":1,"trap_inj":2,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"snow"},{"id":"e3037","day":89,"season":3,"sday":29,"kind":"night","imp":2,"text":"Ottoline follows strange lights away from the camp on floor 1 of Emberdeep, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"emberdeep","wx":"snow"},{"id":"e3071","day":90,"season":3,"sday":30,"kind":"gear","imp":1,"text":"In a sealed space off the hall of old kings on floor 1 of Emberdeep, Fenwick finds a Sturdy Delver's Strap and puts it on. Sturdy: a little better protected (+1.5 armour).","heroes":["h17"],"parties":["p5"],"loc":"emberdeep","wx":"storm"},{"id":"e3072","day":90,"season":3,"sday":30,"kind":"fight","imp":3,"text":"In the anvil rows on floor 1 of Emberdeep, 4 Fire Elementals get in the Green Arrows' way, briefly. Bramble's Lunge knocked half the fight out of the fire elemental. Loot: 7 ember cores, 5 living coals.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"emberdeep","fight":"f221","foes":["fire_elemental","fire_elemental","fire_elemental"],"where":"in the anvil rows on floor 1 of Emberdeep","won":true,"close":false,"shape":"place","reworded":-17,"wx":"storm"},{"id":"e3073","day":90,"season":3,"sday":30,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Emberdeep at a steady pace: 3 rooms (a sealed space off the hall of old kings, the mint, the anvil rows).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"emberdeep","pace":"steady","stats":{"rooms":3,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great","common"],"fears":0,"wild":[]},"wx":"storm"},{"id":"e3074","day":90,"season":3,"sday":30,"kind":"talent","imp":2,"text":"Bramble bets Ottoline a silver that Ottoline can't touch Bramble's sleeve with a stick. Ottoline tries for an hour. Wager of Honour, the way the drill-yards teach it.","heroes":["h13","h14"],"parties":["p5"],"loc":"emberdeep","skill":"wager_of_honour","wx":"storm"},{"id":"e3089","day":90,"season":3,"sday":30,"kind":"delve_done","imp":3,"text":"Emberdeep, 2 days on: The Green Arrows come up blinking at the daylight. They reached floor 1, cleared 7 rooms, came across a sealed space off the hall of old kings and the mint, mapped 13% of it and came away with 120 silver between them. Between every crew so far, Emberdeep is barely touched (8%).","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"emberdeep","days":2,"bottom":false,"rooms":["a sealed space off the hall of old kings","the mint"],"gold":120,"wx":"storm"},{"id":"e3091","day":90,"season":3,"sday":30,"kind":"night","imp":1,"text":"Fenwick tells a ghost story by the fire outside Emberdeep. Ottoline sleeps with a hand on her weapon.","heroes":["h17","h13","h14"],"parties":["p5"],"loc":"emberdeep","wx":"storm"},{"id":"e3103","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Scarlet Thorns, never to retreat (sworn in season 2); The Thunder of Frosthold, to share every coin (sworn in season 2); The Green Arrows, to die rich (sworn in season 2); The Tidal Ledger, never to retreat (sworn in season 2); The Silver Hounds, never to pay a toll (sworn in season 2); Jade Wall, to keep the peace: never draw first on another hero (sworn in season 1); Brix, never to pay a toll (sworn in season 2); Rook, to keep the peace: never draw first on another hero (sworn in season 2); and 1 more. Every one of them held.","heroes":["h1","h15","h17"],"parties":["p1","p10","p3","p5","p7","p8"]}],"roles":{"h13":"Blade","h14":"Healer","h17":"Leader · Quartermaster"},"quest":{"what":"Delve","where":"Emberdeep","why":"chasing a rumour: about 56 silver a day each, risk modest; Ottoline's last chance at the dream before the age ends","floor":0,"floors":4},"tactics":{"front":["h13","h14"],"back":["h17"],"plan":"Bramble and Ottoline hold the front; Fenwick picks off whatever gets close; Ottoline keeps everyone standing.","traits":{"boldness":0.3,"risk":0.35,"greed":-0.03,"sociability":0.28,"honor":0.1,"curiosity":-0.12,"temper":0.04,"loyalty":-0.28},"mix":"2 bows, 1 blade","notes":[],"style":["reckless","skirmishers"],"skills":[{"label":"Damage","skills":[{"hero":"h13","id":"hammer_down","name":"Hammer Down","desc":"Forging technique, applied to faces.","tags":["craft"],"rank":1,"uses":32},{"hero":"h14","id":"cleave","name":"Cleave","desc":"Hits everything in the front rank.","tags":["rage"],"rank":3,"uses":29},{"hero":"h17","id":"caltrops","name":"Caltrops","desc":"A handful of spikes, scattered where feet go.","tags":["craft","stealth"],"rank":1,"uses":27},{"hero":"h13","id":"lunge","name":"Lunge","desc":"Long step, longer reach.","tags":["crit"],"rank":3,"uses":25},{"hero":"h13","id":"shield_bash","name":"Shield Bash","desc":"Rings their bell.","tags":["guard"],"rank":1,"uses":23},{"hero":"h17","id":"bear_trap","name":"Bear Trap","desc":"Sprung, clamped, and very sorry for itself.","tags":["craft"],"rank":1,"uses":17},{"hero":"h17","id":"repeater","name":"Repeater","desc":"Built from a mousetrap and spite. Fires three.","tags":["craft"],"rank":2,"uses":16},{"hero":"h13","id":"disarm","name":"Disarm","desc":"A twist of the wrist and their sword is on the floor.","tags":["crit"],"rank":3,"uses":12},{"hero":"h14","id":"turn_undead","name":"Turn Undead","desc":"Begone.","tags":["holy"],"rank":1,"uses":9},{"hero":"h17","id":"spring_net","name":"Spring Net","desc":"Fires a weighted net from a tube. The tube was a drainpipe on Tuesday.","tags":[],"rank":1,"uses":5},{"hero":"h13","id":"flurry","name":"Flurry","desc":"Three cuts in a heartbeat.","tags":["crit"],"rank":2,"uses":4},{"hero":"h17","id":"field_ballista","name":"Field Ballista","desc":"Assembled in four minutes. Disassembles goblins in one.","tags":["craft"],"rank":1,"uses":3},{"hero":"h13","id":"blade_dance","name":"Blade Dance","desc":"Steel in every direction, elegantly.","tags":["crit"],"rank":1,"uses":0}]},{"label":"Healing","skills":[{"hero":"h14","id":"prayer_of_healing","name":"Prayer of Healing","desc":"Everybody, bow your heads.","tags":["holy","heal"],"rank":3,"uses":11},{"hero":"h14","id":"lay_on_hands","name":"Lay on Hands","desc":"A warm palm, a closed wound.","tags":["holy","heal"],"rank":2,"uses":4},{"hero":"h14","id":"mend_wounds","name":"Mend Wounds","desc":"Knits flesh with a word.","tags":["heal","holy"],"rank":2,"uses":2},{"hero":"h14","id":"miracle","name":"Miracle","desc":"Witnesses still argue about what they saw.","tags":["holy","heal"],"rank":1,"uses":2}]},{"label":"Defence","skills":[{"hero":"h14","id":"hold_the_line","name":"Hold the Line","desc":"Nobody steps back. Nobody.","tags":["guard","command"],"rank":2,"uses":35},{"hero":"h17","id":"tailwind","name":"Tailwind","desc":"The wind is suddenly on everyone's side.","tags":["storm","travel"],"rank":1,"uses":21}]},{"label":"Tricks","skills":[{"hero":"h17","id":"trip_wire","name":"Trip Wire","desc":"Strung across the path before anyone noticed.","tags":["craft","stealth"],"rank":1,"uses":18},{"hero":"h13","id":"blade_dancer","name":"Blade Dancer","desc":"Fights like it's a waltz and the enemy forgot the steps.","tags":[],"rank":1,"uses":15},{"hero":"h17","id":"smoke_bomb","name":"Smoke Bomb","desc":"Cough. Gone.","tags":["stealth"],"rank":2,"uses":7},{"hero":"h13","id":"first_into_the_breach","name":"First Into the Breach","desc":"Already halfway across the room when someone says 'wait'.","tags":[],"rank":1,"uses":5},{"hero":"h14","id":"living_saint","name":"Living Saint","desc":"Small miracles, daily. Paperwork, endless.","tags":[],"rank":1,"uses":3},{"hero":"h14","id":"frenzy","name":"Frenzy","desc":"When a friend falls, sees red.","tags":["rage"],"rank":1,"uses":1},{"hero":"h13","id":"frenzy","name":"Frenzy","desc":"When a friend falls, sees red.","tags":["rage"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h17","id":"shadowstep","name":"Shadowstep","desc":"Steps into one shadow and out of another.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h17","id":"evasive","name":"Evasive","desc":"Hard to pin down.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h17","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0},{"hero":"h13","id":"precision","name":"Precision","desc":"Finds the gap every time.","tags":["crit"],"rank":2,"uses":0},{"hero":"h13","id":"perfect_form","name":"Perfect Form","desc":"Has practised this exact moment ten thousand times.","tags":["crit"],"rank":1,"uses":0},{"hero":"h13","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0},{"hero":"h14","id":"steady_nerves","name":"Steady Nerves","desc":"Doesn't flinch. Neither does the party.","tags":["holy"],"rank":1,"uses":0},{"hero":"h14","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h17","id":"lockpicking","name":"Lockpicking","desc":"Doors are suggestions.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h17","id":"rooftop_runner","name":"Rooftop Runner","desc":"Takes the high road. Literally.","tags":["stealth","travel"],"rank":1,"uses":0},{"hero":"h17","id":"good_listener","name":"Good Listener","desc":"People tell them things. Then feel better.","tags":["lore"],"rank":1,"uses":0},{"hero":"h17","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0},{"hero":"h17","id":"cobbler","name":"Cobbler","desc":"New soles for old boots, old roads for new soles.","tags":["craft","travel"],"rank":1,"uses":0},{"hero":"h17","id":"trap_seller","name":"Trap Seller","desc":"Every farmer with a fox problem knows their name.","tags":["craft"],"rank":1,"uses":0},{"hero":"h17","id":"tin_can_line","name":"Tin-Can Line","desc":"Cans on a string round the camp. Nothing sneaks up. Nobody sleeps.","tags":["nature","craft"],"rank":1,"uses":0},{"hero":"h17","id":"smokehouse","name":"Smokehouse","desc":"Smoked fish, smoked sausage, smoked everything.","tags":[],"rank":1,"uses":0},{"hero":"h17","id":"spice_box","name":"Spice Box","desc":"Carries a tin of spices the size of a hymnal, and uses it.","tags":[],"rank":1,"uses":0},{"hero":"h17","id":"wanderlust","name":"Wanderlust","desc":"Every road teaches something.","tags":["travel"],"rank":1,"uses":0},{"hero":"h13","id":"speechmaker","name":"Speechmaker","desc":"Has a speech. Has several.","tags":["command"],"rank":1,"uses":0},{"hero":"h13","id":"fencing_lessons","name":"Fencing Lessons","desc":"Teaches the basics. Charges for the advanced.","tags":["crit"],"rank":2,"uses":0},{"hero":"h13","id":"wager_of_honour","name":"Wager of Honour","desc":"Bets the room they can't be touched. Collects.","tags":["crit"],"rank":1,"uses":0},{"hero":"h13","id":"brewer","name":"Brewer","desc":"Every camp has a bubbling pot that isn't soup.","tags":[],"rank":1,"uses":0},{"hero":"h13","id":"firekeeper","name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"rank":1,"uses":0},{"hero":"h14","id":"ice_fishing","name":"Ice Fishing","desc":"Cuts a hole, sits, waits, wins.","tags":[],"rank":1,"uses":0},{"hero":"h14","id":"bedside_manner","name":"Bedside Manner","desc":"Makes you feel better before the medicine does.","tags":["heal"],"rank":1,"uses":0},{"hero":"h14","id":"field_chaplain","name":"Field Chaplain","desc":"Patches the cut, then asks how they're really doing.","tags":["heal","holy"],"rank":2,"uses":0},{"hero":"h14","id":"wayside_shrines","name":"Wayside Shrines","desc":"Sweeps out every roadside shrine. The priests start leaving the door open.","tags":["holy"],"rank":1,"uses":0}]}],"share":[{"hero":"h17","dmg":3287,"healed":0,"taken":0,"kills":16,"row":"back"},{"hero":"h13","dmg":5140,"healed":0,"taken":544,"kills":18,"row":"front"},{"hero":"h14","dmg":812,"healed":741,"taken":411,"kills":3,"row":"front"}],"ground":{"name":"The Sunken Vault","fights":11}},"trophies":[{"boss":"Old Grizzlemaw","monster":"cave_bear","place":"The Wolf Den","day":13,"season":1,"fight":"f37"},{"boss":"Vessimir the Unburied","monster":"necromancer","place":"The Ashveil Crypts","day":27,"season":1,"fight":"f85"}]};